#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "Google Play Store Release Setup"

# ── Stage 1: Git Safety Check ─────────────────────────────────────────────
stage "Git Safety Check"
say "Ensuring private keys and production secrets are never committed to git."
step "Verifying .gitignore contains *.jks, key.properties, and config/prod.json..."

local missing_rules=0
for rule in "*.jks" "*.keystore" "android/key.properties" "config/prod.json"; do
  if ! grep -qF "$rule" .gitignore 2>/dev/null; then
    echo "$rule" >> .gitignore
    missing_rules=$((missing_rules + 1))
  fi
done

if (( missing_rules > 0 )); then
  say "Added missing rules to .gitignore."
else
  say "All secret patterns already ignored in .gitignore."
fi
note "✓ .gitignore is secure."
pause "Press Enter to continue"

# ── Stage 2: Android Release Keystore ─────────────────────────────────────
stage "Generate Android Upload Keystore"
say "Google Play requires an upload keystore to sign and verify your app bundle."
local KEYSTORE_FILE="android/app/upload-keystore.jks"

ask ANDROID_KEY_ALIAS "Keystore alias [upload]:"
ANDROID_KEY_ALIAS="${ANDROID_KEY_ALIAS:-upload}"

ask_secret ANDROID_KEYSTORE_PASSWORD "Enter Keystore password:"
ask_secret ANDROID_KEY_PASSWORD "Enter Key password (press Enter if same as keystore password):"
ANDROID_KEY_PASSWORD="${ANDROID_KEY_PASSWORD:-$ANDROID_KEYSTORE_PASSWORD}"

if [[ -f "$KEYSTORE_FILE" ]]; then
  warn "$KEYSTORE_FILE already exists."
  if confirm "Overwrite existing keystore file?"; then
    rm -f "$KEYSTORE_FILE"
  fi
fi

if [[ ! -f "$KEYSTORE_FILE" ]]; then
  step "Generating 2048-bit RSA upload keystore with keytool..."
  keytool -genkey -v \
    -keystore "$KEYSTORE_FILE" \
    -alias "$ANDROID_KEY_ALIAS" \
    -keyalg RSA \
    -keysize 2048 \
    -validity 10000 \
    -storepass "$ANDROID_KEYSTORE_PASSWORD" \
    -keypass "$ANDROID_KEY_PASSWORD" \
    -dname "CN=Teman Lari, OU=Mobile, O=Teman Lari, L=Jakarta, ST=Jakarta, C=ID"
  say "✓ Keystore generated at $KEYSTORE_FILE"
else
  say "Using existing $KEYSTORE_FILE"
fi

step "Writing android/key.properties for Gradle builds..."
cat > android/key.properties <<EOF
storePassword=$ANDROID_KEYSTORE_PASSWORD
keyPassword=$ANDROID_KEY_PASSWORD
keyAlias=$ANDROID_KEY_ALIAS
storeFile=upload-keystore.jks
EOF
say "✓ Generated android/key.properties"

write_env ANDROID_KEY_ALIAS "$ANDROID_KEY_ALIAS"
write_env ANDROID_KEYSTORE_PASSWORD "$ANDROID_KEYSTORE_PASSWORD"
write_env ANDROID_KEY_PASSWORD "$ANDROID_KEY_PASSWORD"
pause "Keystore configured. Press Enter to proceed to Strava configuration"

# ── Stage 3: Strava Production Credentials ───────────────────────────────
stage "Strava API Production Credentials"
say "Teman Lari requires production Strava API credentials for OAuth login."
open_url "https://www.strava.com/settings/api"

step "In Strava API settings, copy your Client ID and Client Secret."
step "Ensure 'Authorization Callback Domain' matches your production setup."

ask STRAVA_CLIENT_ID "Paste Strava Client ID:"
ask_secret STRAVA_CLIENT_SECRET "Paste Strava Client Secret:"
ask STRAVA_REDIRECT_URI "Paste Strava Redirect URI [com.halixm.temanlari://redirect]:"
STRAVA_REDIRECT_URI="${STRAVA_REDIRECT_URI:-com.halixm.temanlari://redirect}"

write_env STRAVA_CLIENT_ID "$STRAVA_CLIENT_ID"
write_env STRAVA_CLIENT_SECRET "$STRAVA_CLIENT_SECRET"
write_env STRAVA_REDIRECT_URI "$STRAVA_REDIRECT_URI"

step "Creating config/prod.json for Flutter --dart-define-from-file..."
mkdir -p config
cat > config/prod.json <<EOF
{
  "STRAVA_CLIENT_ID": "$STRAVA_CLIENT_ID",
  "STRAVA_CLIENT_SECRET": "$STRAVA_CLIENT_SECRET",
  "STRAVA_REDIRECT_URI": "$STRAVA_REDIRECT_URI"
}
EOF
say "✓ Saved config/prod.json"
pause "Press Enter to proceed to GitHub Secrets synchronization"

# ── Stage 4: Sync GitHub Secrets for CI/CD ────────────────────────────────
stage "Sync Secrets to GitHub Actions"
say "Pushing release signing and API credentials to GitHub for automated CI/CD."

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  step "Encoding upload-keystore.jks to base64..."
  local B64_KEYSTORE=""
  if base64 --help 2>&1 | grep -q -- "-w"; then
    B64_KEYSTORE=$(base64 -w 0 < "$KEYSTORE_FILE")
  else
    B64_KEYSTORE=$(base64 < "$KEYSTORE_FILE" | tr -d '\r\n')
  fi

  set_secret ANDROID_KEYSTORE_BASE64 "$B64_KEYSTORE"
  set_secret ANDROID_KEYSTORE_PASSWORD "$ANDROID_KEYSTORE_PASSWORD"
  set_secret ANDROID_KEY_ALIAS "$ANDROID_KEY_ALIAS"
  set_secret ANDROID_KEY_PASSWORD "$ANDROID_KEY_PASSWORD"
  set_secret STRAVA_CLIENT_ID "$STRAVA_CLIENT_ID"
  set_secret STRAVA_CLIENT_SECRET "$STRAVA_CLIENT_SECRET"
  set_secret STRAVA_REDIRECT_URI "$STRAVA_REDIRECT_URI"
else
  warn "GitHub CLI (gh) not logged in or not installed."
  warn "To sync later manually, run: gh secret set ANDROID_KEYSTORE_BASE64 < (base64 of upload-keystore.jks)"
fi
pause "Press Enter to proceed to Google Play Console initialization"

# ── Stage 5: Google Play Console Account & App ────────────────────────────
stage "Google Play Console App Setup"
say "Registering the application entry and mandatory store disclosures."
open_url "https://play.google.com/console/developers"

step "1. If not already done, complete account registration ($25 fee + ID verification)."
step "2. Click 'Create app' on the dashboard."
step "   - App name: Teman Lari"
step "   - Default language: English (United States) or Indonesian"
step "   - App or game: App"
step "   - Free or paid: Free"
step "3. Under Policy > App content, complete the following:"
step "   - Privacy Policy: Link to your hosted privacy policy (required for GPS & sensors)."
step "   - App access: Declare all functionality is available without credentials (or provide demo)."
step "   - Data Safety: Declare Location (GPS run tracking) and Physical Activity (step counting)."
pause "Press Enter once the app entry is created in Play Console"

# ── Stage 6: Build & Verify Release App Bundle (.aab) ────────────────────
stage "Build Release App Bundle (.aab)"
say "Building production Android App Bundle signed with your release key."

if confirm "Build Android App Bundle (.aab) right now?"; then
  step "Running: flutter build appbundle --flavor prod --dart-define-from-file=config/prod.json --release"
  flutter build appbundle --flavor prod --dart-define-from-file=config/prod.json --release
  local AAB_PATH="build/app/outputs/bundle/prodRelease/app-prod-release.aab"
  if [[ -f "$AAB_PATH" ]]; then
    say "✓ Successfully generated bundle:"
    note "  $AAB_PATH"
  else
    warn "AAB build completed, check build/app/outputs/bundle/ for output file."
  fi
else
  say "Skipping build command. You can run it manually when ready:"
  note "flutter build appbundle --flavor prod --dart-define-from-file=config/prod.json --release"
fi
pause "Press Enter to proceed to Closed Testing setup"

# ── Stage 7: Closed Testing & 14-Day Tester Requirement ──────────────────
stage "Closed Testing Track Setup (14-Day Gate)"
say "Setting up the closed testing track for Google Play verification."
open_url "https://play.google.com/console/developers"

step "1. In Google Play Console, select 'Teman Lari' > Testing > Closed testing."
step "2. Click 'Create track' (or manage Closed testing - Alpha track)."
step "3. Create a new release, upload 'build/app/outputs/bundle/prodRelease/app-prod-release.aab'."
step "4. Enter release notes, review and start rollout to Closed testing."
step "5. Under Testers tab: add at least 20 tester email addresses."
step "   ⚠ CRITICAL: Google requires 20 testers opted-in for 14 continuous days"
step "   before personal accounts can apply for Production access."
step "6. Copy the Opt-in URL and send it to your 20 testers."
pause "Press Enter to complete wizard"

finish
}

run_wizard "$@"; exit
